import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate } from '../remotionShim';


export type LifeTimelineProps = Record<string, any>;

const LifeTimeline: React.FC<LifeTimelineProps> = ({
  backgroundColor = "#0f172a", // Slate 900
  transparentBackground = false,
  barFillColorStart = "#38bdf8", // Sky 400
  barFillColorEnd = "#ec4899", // Pink 500
  durationInSeconds = 10,
  barHeight = 40,
  edgeSoftness = 10,
}) => {
  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();
  const durationInFrames = durationInSeconds * fps;

  // Background handling
  const finalBgColor = transparentBackground ? "transparent" : backgroundColor;

  // Timeline Progress (Linear fill over the duration)
  const startFillFrame = 10;
  const fillDuration = Math.max(1, durationInFrames - startFillFrame - 15);
  
  const progress = interpolate(
    frame,
    [startFillFrame, startFillFrame + fillDuration],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Styles
  const containerStyle: React.CSSProperties = {
    position: "absolute",
    top: 0,
    left: 0,
    width: "100%",
    height: "100%",
    backgroundColor: finalBgColor,
    display: "flex",
    flexDirection: "column",
    justifyContent: "center",
    alignItems: "center",
  };

  const timelineContainerStyle: React.CSSProperties = {
    position: "relative",
    width: "100%",
    height: barHeight,
    display: "flex",
    alignItems: "center",
  };

  const fillStyle: React.CSSProperties = {
    position: "absolute",
    left: 0,
    top: 0,
    height: "100%",
    width: `${progress * 100}%`,
    background: `linear-gradient(to right, ${barFillColorStart}, ${barFillColorEnd})`,
    backgroundSize: `${width}px 100%`,
    backgroundAttachment: "fixed",
    boxShadow: edgeSoftness > 0 ? `0 0 ${edgeSoftness}px ${barFillColorEnd}` : "none",
    transition: "none", // Critical for Remotion
  };

  return (
    <AbsoluteFill style={containerStyle}>
      <div style={timelineContainerStyle}>
        <div style={fillStyle} />
      </div>
    </AbsoluteFill>
  );
};

export default LifeTimeline;